import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  // Plane dimensions based on typical aspect ratio (512 / 320 = 1.6)
  const PLANE_WIDTH = 1.6;
  const PLANE_HEIGHT = 1.0;

  const geometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const material = new MeshBasicNodeMaterial();

  const plane = new Mesh(geometry, material);
  root.add(plane);

  let texture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No cinematic primitives for this node
  const primitiveInstances = [];

  const cleanup = () => {
    // Dispose material, geometry, and texture
    if (material) material.dispose();
    if (geometry) geometry.dispose();
    if (texture) texture.dispose();

    // Cleanup any primitive resources
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });

    // Kill any GSAP timelines that might have been created
    gsap.globalTimeline.clear();
  };

  root.userData = {
    handlers: {},
    cleanup,
  };

  return root;
}
